Toggle Flameskull Illumination.command:
if (token.name !== "Flameskull") return ui.notifications.info("This Macro can only be used on a Flameskull");
console.log(token.light.bright);
if (token.document.light.bright === 15) {
    await token.document.update({"light.bright": 0, "light.dim": 15})
} else {
    await token.document.update({"light.bright": 15, "light.dim": 30})
}

Rotate the Hidden Sanctum.command:
/**
 * Intended for use with Map 6.4: Crypt of the Talhund.
 * Affects area P14. 
 * Toggles orientation of sanctum tile and associated walls. Also opens the secret doors dividing rooms P11 and P15.
 */

if (!game.modules.get("dnd-phandelver-below")?.active) ui.notifications.warn("The Phandelver and Below module must be enabled for this macro to function correctly.");

const dividerWalls = ['QKtXLW6kgPkxeiSN', 'oeFOWnf3VRMRNsNL'];
const toggleState = dividerWalls.map( id => ({
  _id: id,
  ds: (canvas.scene.walls.get(id).ds == CONST.WALL_DOOR_STATES.CLOSED) ? CONST.WALL_DOOR_STATES.OPEN : CONST.WALL_DOOR_STATES.CLOSED,
}))

canvas.scene.updateEmbeddedDocuments('Wall', toggleState);

const sanctum = canvas.tiles.placeables.find( t => t.document.texture.src === "modules/dnd-phandelver-below/assets/scenes/crypt-of-the-talhund/crypt-of-the-talhund-rotating-tile.webp" );

const rotation = sanctum?.document.rotation == 0 ? -15 : 15;

game.modules.get('dnd-phandelver-below').utils.spinTile(sanctum?.id, rotation);

Spin the Rolling Eye.command:
/**
 * Intended for use with Map 7.5: Labyrinth of Eyes.
 * Affects area L3. 
 * Rotates clockwise. Hold alt to rotate counter-clockwise.
 */

if (!game.modules.get("dnd-phandelver-below")?.active) ui.notifications.warn("The Phandelver and Below module must be enabled for this macro to function correctly.");
const counterclockwise = event.altKey ? true : false;
game.modules.get('dnd-phandelver-below').utils.spinTileSystem(counterclockwise);

