Configure Token Vision.command:
const module = game.modules.get('dnd-phandelver-below');
const title = game.i18n.localize("PBSO.CONFIGURE_VISION.Title");
const content = game.i18n.localize("PBSO.CONFIGURE_VISION.Content");
const enable = game.i18n.localize("PBSO.CONFIGURE_VISION.Enable");
const disable = game.i18n.localize("PBSO.CONFIGURE_VISION.Disable");


new Dialog({
    title: title,
    content: `<p>${content}</p>`,
    buttons: {
        enable: {
            label: enable,
            callback: () => module.utils.configureTokenVision(true)
        },
        disable: {
            label: disable,
            callback: () => module.utils.configureTokenVision(false)
        }
    }
}).render(true)
